{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q17",
      "policy_quote": "You should not make up any information or knowledge or procedures not provided by the user or the tools, or give subjective recommendations or comments.",
      "requirement": "The assistant must only provide information or actions explicitly supported by user input or tool outputs, without speculation or subjective commentary."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q17",
      "policy_quote": "You should at most make one tool call at a time, and if you take a tool call, you should not respond to the user at the same time. If you respond to the user, you should not make a tool call at the same time.",
      "requirement": "The assistant must not respond to the user while making a tool call, and must not make a tool call while responding to the user."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q17",
      "policy_quote": "You should deny user requests that are against this policy.",
      "requirement": "The assistant must deny any requests that violate the policy, including those requiring actions outside its scope."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q17",
      "policy_quote": "You should transfer the user to a human agent if and only if the request cannot be handled within the scope of your actions.",
      "requirement": "If the user's request cannot be handled within the assistant's allowed actions, the assistant must first call `transfer_to_human_agents` and then inform the user of the transfer."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q20",
      "policy_quote": "An order can only be exchanged if its status is 'delivered', and you should check its status before taking the action.",
      "requirement": "The assistant must confirm the order status is 'delivered' before proceeding with the exchange."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q20",
      "policy_quote": "For a delivered order, each item can be exchanged to an available new item of the same product but of different product option. There cannot be any change of product types.",
      "requirement": "The new item must belong to the same product type as the exchanged item, allowing only variations in product options."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q20",
      "policy_quote": "The user must provide a payment method to pay or receive refund of the price difference. If the user provides a gift card, it must have enough balance to cover the price difference.",
      "requirement": "The assistant must ensure the provided payment method (e.g., PayPal, gift card) is valid and capable of covering any price difference."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q20",
      "policy_quote": "After user confirmation, the order status will be changed to 'exchange requested', and the user will receive an email regarding how to return items.",
      "requirement": "The assistant must obtain explicit user confirmation (e.g., 'yes') before executing the exchange tool call."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q17",
      "policy_quote": "Exchange or modify order tools can only be called once per order.",
      "requirement": "The assistant must ensure no prior exchange or modification has been made for this order before proceeding."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q17",
      "policy_quote": "You should not make up any information or knowledge or procedures not provided by the user or the tools, or give subjective recommendations or comments.",
      "requirement": "The assistant must ensure all details (e.g., item IDs, payment method) are accurate and provided by the user or tools, without assumptions."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q17",
      "policy_quote": "You should at most make one tool call at a time.",
      "requirement": "The assistant must not make multiple tool calls simultaneously; only one exchange tool call is allowed per action."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q20",
      "policy_quote": "In particular, remember to remind the customer to confirm they have provided all items to be exchanged.",
      "requirement": "The assistant must ensure the user has confirmed all items to be exchanged before proceeding with the tool call."
    }
  ]
}
